#!/usr/bin/env python3
"""Write data/trivia.json. Numeric answers come from data/countries.json."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
COUNTRIES = json.loads((ROOT / "data" / "countries.json").read_text())["countries"]
BY = {country["iso2"]: country for country in COUNTRIES}

ITEMS = []


def add(kind, id_, difficulty, region, question, choices, answer, explain):
    if answer < 0 or answer >= len(choices):
        raise SystemExit(f"bad answer {id_}")
    if len(set(choices)) != len(choices):
        raise SystemExit(f"dup choice {id_} {choices}")
    ITEMS.append(
        {
            "id": id_,
            "kind": kind,
            "difficulty": difficulty,
            "region": region,
            "q": question,
            "choices": choices,
            "answer": answer,
            "explain": explain,
        }
    )


def name(iso):
    return BY[iso]["nameKo"]


def generated():
    area = sorted(COUNTRIES, key=lambda country: country["areaKm2"], reverse=True)
    pop = sorted(
        [country for country in COUNTRIES if country["populationRank"]],
        key=lambda country: country["population"],
        reverse=True,
    )
    dense = sorted(
        [country for country in COUNTRIES if country["densityRank"]],
        key=lambda country: country["density"],
        reverse=True,
    )
    specs = [
        ("area-1", "easy", "면적이 가장 넓은 나라는?", area[0], "mledoze/countries 면적 1위입니다."),
        ("area-2", "medium", "면적 2위는?", area[1], "캐나다입니다. 1위는 러시아입니다."),
        ("area-3", "medium", "면적 3위는?", area[2], "중국입니다. 대만은 별도 카드라 이 숫자에 더하거나 빼지 않았습니다."),
        ("area-4", "medium", "면적 4위는?", area[3], "미국입니다. 속령을 모두 더한 값인지는 자료마다 달라 데이터셋 숫자를 그대로 씁니다."),
        ("area-5", "medium", "면적 5위는?", area[4], "브라질입니다."),
        ("pop-1", "easy", "세계은행 2025년 인구가 가장 많은 나라는?", pop[0], "인도입니다. 중국이 아닙니다."),
        ("pop-2", "easy", "세계은행 2025년 인구 2위는?", pop[1], "중국입니다. 1위는 인도입니다."),
        ("pop-3", "easy", "세계은행 2025년 인구 3위는?", pop[2], "미국입니다."),
        ("pop-4", "medium", "세계은행 2025년 인구 4위는?", pop[3], "인도네시아입니다."),
        ("pop-5", "medium", "세계은행 2025년 인구 5위는?", pop[4], "파키스탄입니다."),
        ("den-1", "easy", "인구 밀도가 가장 높은 나라는? (순위가 있는 나라)", dense[0], "모나코입니다. 바티칸은 인구 순위 밖입니다."),
        ("den-2", "medium", "인구 밀도 2위는? (순위가 있는 나라)", dense[1], "싱가포르입니다."),
        ("den-low", "medium", "인구 밀도가 가장 낮은 나라는? (순위가 있는 나라)", dense[-1], "몽골입니다."),
    ]
    for id_, difficulty, question, country, explain in specs:
        pool = [country] + [item for item in (area if "면적" in question else pop) if item["iso2"] != country["iso2"]][:3]
        if "밀도" in question:
            pool = [country] + [item for item in dense if item["iso2"] != country["iso2"]][:3]
            if "낮은" in question:
                pool = [dense[-1], dense[0], dense[1], dense[2]]
        choices = [item["nameKo"] for item in pool]
        add("trivia", f"gen-{id_}", difficulty, "world", question, choices, choices.index(country["nameKo"]), explain + f" 값의 출처는 이 사이트의 /sources 입니다.")

    un_small = sorted([country for country in COUNTRIES if country["status"] == "un"], key=lambda country: country["areaKm2"])
    add(
        "trivia",
        "gen-small-un",
        "easy",
        "Europe",
        "유엔 회원국 가운데 이 자료의 면적이 가장 작은 나라는?",
        [un_small[0]["nameKo"], un_small[1]["nameKo"], "바티칸", un_small[2]["nameKo"]],
        0,
        "모나코(2.02km²)입니다. 바티칸이 더 작지만 유엔 회원국이 아니라 옵서버입니다.",
    )
    add(
        "trivia",
        "gen-small-all",
        "easy",
        "Europe",
        "이 사이트가 다루는 197곳 가운데 면적이 가장 작은 곳은?",
        ["바티칸", "모나코", "나우루", "투발루"],
        0,
        "바티칸 0.44km²입니다. 유엔 옵서버로 적어 두었습니다.",
    )
    add(
        "trivia",
        "gen-billion",
        "easy",
        "world",
        "세계은행 2025년 인구가 10억 명을 넘는 나라는 몇 곳인가요?",
        ["1곳", "2곳", "3곳", "5곳"],
        1,
        "인도와 중국입니다. 미국은 3위지만 10억을 넘지 않습니다.",
    )
    add(
        "trivia",
        "gen-over9m",
        "hard",
        "world",
        "이 자료에서 면적이 900만 km²를 넘는 나라는 몇 곳인가요?",
        ["3곳", "4곳", "5곳", "6곳"],
        1,
        "러시아·캐나다·중국·미국입니다. 브라질은 약 852만 km²로 그 아래입니다.",
    )
    same = [country["nameKo"] for country in COUNTRIES if country["timezones"] and all(zone["stdMin"] == 540 for zone in country["timezones"])]
    add(
        "trivia",
        "gen-utc9-count",
        "hard",
        "world",
        "이 자료에서 표준시가 한국과 같은 나라는 몇 곳인가요? 한국 포함",
        ["3곳", "4곳", "5곳", "6곳"],
        2,
        "대한민국, 조선민주주의인민공화국, 일본, 동티모르, 팔라우입니다. " + ", ".join(same) + ".",
    )
    ll = [country for country in COUNTRIES if country["landlocked"]]
    add(
        "trivia",
        "gen-ll-count",
        "hard",
        "world",
        "이 자료에서 내륙국으로 표시된 곳은 몇 곳인가요?",
        [str(len(ll) - 2) + "곳", str(len(ll) - 1) + "곳", str(len(ll)) + "곳", str(len(ll) + 1) + "곳"],
        2,
        f"{len(ll)}곳입니다. 바티칸·코소보처럼 유엔 비회원도 자료 표시를 따릅니다. 카스피해만 접한 나라도 내륙으로 분류된 경우가 있습니다.",
    )
    coast = [country for country in COUNTRIES if not country["landlocked"]]
    for index, country in enumerate(ll):
        if index % 3:
            continue
        wrongs = [item["nameKo"] for item in coast if item["region"] == country["region"]][:3]
        if len(wrongs) < 3:
            wrongs = [item["nameKo"] for item in coast if item["nameKo"] not in wrongs][: 3 - len(wrongs)] + wrongs
        choices = [country["nameKo"], *wrongs[:3]]
        add(
            "trivia",
            f"gen-ll-{country['iso2']}",
            "medium" if country["populationRank"] and country["populationRank"] <= 80 else "hard",
            country["region"],
            "다음 중 이 자료에서 내륙국인 나라는?",
            choices,
            0,
            f"{country['nameKo']}는 바다와 닿지 않는 내륙국으로 표시되어 있습니다.",
        )
    pen = BY["KR"]["areaKm2"] + BY["KP"]["areaKm2"]
    nearest = sorted(
        [country for country in COUNTRIES if country["iso2"] not in ("KR", "KP")],
        key=lambda country: abs(country["areaKm2"] - pen),
    )[:4]
    add(
        "trivia",
        "gen-peninsula",
        "hard",
        "Americas",
        "남북한 면적을 더한 값과 이 자료에서 가장 가까운 나라는?",
        [country["nameKo"] for country in nearest],
        0,
        f"한반도 남북 합은 {round(pen):,}km²입니다. 가장 가까운 나라는 {nearest[0]['nameKo']}({round(nearest[0]['areaKm2']):,}km²)입니다.",
    )


