def main():
    generated()
    for id_, kind, difficulty, region, question, choices, answer, explain in HAND + EXTRA:
        add(kind, id_, difficulty, region, question, choices, answer, explain)
    ids = [item["id"] for item in ITEMS]
    if len(ids) != len(set(ids)):
        dupes = sorted({item for item in ids if ids.count(item) > 1})
        raise SystemExit(f"duplicate ids {dupes[:10]}")
    kinds = {}
    for item in ITEMS:
        kinds[item["kind"]] = kinds.get(item["kind"], 0) + 1
    if kinds.get("trivia", 0) < 200:
        raise SystemExit(f"trivia bank too small {kinds}")
    if kinds.get("flag", 0) < 30 or kinds.get("ox", 0) < 30:
        raise SystemExit(f"mode bank too small {kinds}")
    for item in ITEMS:
        shift = sum(ord(char) for char in item["id"]) % len(item["choices"])
        if shift:
            item["choices"] = item["choices"][shift:] + item["choices"][:shift]
            item["answer"] = (item["answer"] - shift) % len(item["choices"])
    path = ROOT / "data" / "trivia.json"
    path.write_text(json.dumps(ITEMS, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("wrote", path, kinds, "total", len(ITEMS))


if __name__ == "__main__":
    main()
